    rec=[{'name':f'Budget {style} {n}','category':'Home Decor','estimated_price':round(per,2),'platform':plats[i%4],'url':url(plats[i%4],n),'reason':f'Suitable for a {room_type} and {style} style.'} for i,n in enumerate(names)]
    return {'planner':'home','budget':budget,'summary':f'A practical {style} {room_type} plan within your budget.','allocation':{'Furniture':round(budget*.45,2),'Lighting':round(budget*.20,2),'Decor':round(budget*.20,2),'Contingency':round(budget*.15,2)},'recommendations':rec,'tips':['Compare final prices and delivery charges.','Keep contingency for unexpected costs.','Prioritize essentials before decor.'],'ai_generated':False}
